SELECT hd.hd_buy_potential, c.c_birth_year, SUM(ws.ws_net_paid) AS total_net_paid, COUNT(*) AS order_count, (SELECT c2.c_email_address FROM customer c2 WHERE c2.c_customer_sk = 6702959) AS sample_email FROM web_sales ws JOIN customer c ON ws.ws_bill_customer_sk = c.c_customer_sk JOIN web_returns wr ON wr.wr_order_number = ws.ws_order_number JOIN household_demographics hd ON c.c_current_hdemo_sk = hd.hd_demo_sk WHERE ws.ws_sold_date_sk = 2451705 AND hd.hd_income_band_sk = 10 GROUP BY hd.hd_buy_potential, c.c_birth_year HAVING SUM(ws.ws_net_paid) > 2495.46
